// DFT: vset[vbat,3] -> en_tm[] -> field[(DMUX_EN,1),(DMUX_SEL,20)] -> a2d_vac3_prst
//      -> VAC3 0->10->0V scan, measure V(DTEST0)=nQON toggle (r 4.059 f 3.738)
